CREATE OR REPLACE FUNCTION lr_serverless_aws_us_catalog.bricksurance_reinsurance.fn_cession_trace(in_policy_number STRING COMMENT 'Policy number, e.g. POL-2026-000001.')
RETURNS STRING
COMMENT 'Which treaties a policy is ceded to, and at what shares. Returns: Semicolon-separated ''treaty @ share'' list; NULL when nothing is ceded.'
RETURN (SELECT array_join(sort_array(collect_list(
          concat(t.treaty_reference, ' @ ', cast(ces.ceded_share AS STRING)))), '; ')
 FROM lr_serverless_aws_us_catalog.bricksurance_reinsurance.cession ces
 JOIN lr_serverless_aws_us_catalog.bricksurance_policy.policy p ON p.policy_id = ces.policy_id
 JOIN lr_serverless_aws_us_catalog.bricksurance_reinsurance.treaty t ON t.treaty_id = ces.treaty_id
 WHERE p.policy_number = in_policy_number);
